{
  "items": [
    {
      "title": "Eurostat – Employment and Labour Force by Sex and Age (Annual Data)",
      "url_or_doi": "https://doi.org/10.2908/LFSI_EMP_A",
      "justification": "Official Eurostat dataset containing annual employment statistics for Germany from 2003 through 2025. Includes employment rates, numbers of employed persons, and breakdowns by sex and age. Particularly useful for examining employment trends during the 2020s, including changes following the COVID-19 pandemic and comparisons with other European countries."
    },
    {
      "title": "Eurostat – Employment and Labour Force by Sex and Age (Quarterly Data)",
      "url_or_doi": "https://doi.org/10.2908/LFSI_EMP_Q",
      "justification": "Provides quarterly employment statistics for Germany, with data extending through the second quarter of 2026. Includes employment rates and breakdowns by sex and age, with seasonally adjusted observations. Suitable for analyzing short-term labor market fluctuations, pandemic-related employment changes, and subsequent recovery patterns."
    },
    {
      "title": "German Federal Statistical Office (Destatis) – National Accounts: Population and Employment, Quarterly Data",
      "url_or_doi": "https://genesis.destatis.de/datenbank/online/statistic/81000/table/81000-0012",
      "justification": "Official German government dataset providing quarterly employment statistics through the national accounts system. Includes original and adjusted data for Germany, with observations covering the 2020s. Particularly relevant for investigating changes in total employment, quarterly labor market developments, and broader economic trends."
    },
    {
      "title": "German Federal Employment Agency – Long-Term Labor Market Time Series",
      "url_or_doi": "https://statistik.arbeitsagentur.de/DE/Navigation/Statistiken/Interaktive-Statistiken/Zeitreihen/Lange-Zeitreihen-Nav.html",
      "justification": "Official time-series datasets published by Germany's Federal Employment Agency (Bundesagentur für Arbeit). Cover employment, unemployment, underemployment, and registered job vacancies. Include monthly and annual observations extending through the 2020s, with geographical breakdowns for Germany, federal states, districts, and regional labor markets. Particularly useful for studying regional employment trends."
    },
    {
      "title": "German Federal Employment Agency – Employment Statistics (Beschäftigte)",
      "url_or_doi": "https://statistik.arbeitsagentur.de/DE/Navigation/Statistiken/Fachstatistiken/Beschaeftigung/Beschaeftigte/Beschaeftigte-Nav.html",
      "justification": "Official administrative employment statistics covering workers subject to social security contributions and marginally employed workers in Germany. Provides employment figures by occupation, industry, region, and other characteristics, including time series covering the 2020s. Particularly valuable for analyzing employment structures, sectoral changes, and regional labor market developments."
    },
    {
      "title": "German Federal Employment Agency – Employment Statistics Database",
      "url_or_doi": "https://statistik.arbeitsagentur.de/DE/Navigation/Statistiken/Interaktive-Statistiken/Datenbanken/Datenbanken-BST-Nav.html",
      "justification": "Interactive database offering customizable German employment statistics and downloadable datasets. Allows researchers to construct employment tables using available demographic, occupational, geographical, and other characteristics. Useful for detailed investigations of employment patterns and structural changes in Germany during the 2020s."
    },
    {
      "title": "OECD Employment Database",
      "url_or_doi": "https://www.oecd.org/en/data/datasets/oecd-employment-database.html",
      "justification": "Comprehensive international employment database maintained by the Organisation for Economic Co-operation and Development. Includes German employment rates, labor force statistics, unemployment indicators, and employment characteristics, with historical time series covering the 2020s. Particularly useful for comparing Germany's employment performance with other OECD countries and examining demographic differences."
    },
    {
      "title": "Eurostat – Employees by European Socio-Economic Group and Employment Contract",
      "url_or_doi": "https://doi.org/10.2908/LFSA_ESEGT",
      "justification": "Eurostat dataset containing annual employment statistics from 2011 through 2025, including Germany. Classifies employees by socio-economic group, employment contract type, and age. Useful for investigating changes in employment arrangements, contractual employment structures, and socioeconomic differences in the German labor market throughout the 2020s."
    },
    {
      "title": "German Federal Statistical Office (Destatis) – Persons Engaged in Economic Activity",
      "url_or_doi": "https://www.destatis.de/EN/Themes/Labour/Labour-Market/Employment/Tables/personse-economic-activity.html",
      "justification": "Official German employment statistics presenting the number of persons engaged in economic activity and changes in employment over time. Includes observations from the 2020s and provides a national statistical perspective on employment developments. Useful for examining changes in overall employment levels and connecting labor market developments with broader economic conditions."
    }
  ]
}
